function handleMultipart (opts = {}) {
  if (!this.isMultipart()) {
    throw new InvalidMultipartContentTypeError()
  }

  this.log.debug('starting multipart parsing')

  let values = []
  let pendingHandler = null

  // only one file / field can be processed at a time
  // "null" will close the consumer side
  const ch = (val) => {
    if (pendingHandler) {
      pendingHandler(val)
      pendingHandler = null
    } else {
      values.push(val)
    }
  }

  const handle = (handler) => {
    if (values.length > 0) {
      const value = values[0]
      values = values.slice(1)
      handler(value)
    } else {
      pendingHandler = handler
    }
  }

  const parts = () => {
    return new Promise((resolve, reject) => {
      handle((val) => {
        if (val instanceof Error) return reject(val)
        resolve(val)
      })
    })
  }

  const body = {}
  let lastError = null
  let currentFile = null
  const request = this.raw
  const busboyOptions = deepmergeAll(
    { headers: request.headers },
    options,
    opts
  )

  this.log.trace({ busboyOptions }, 'Providing options to busboy')
  const bb = busboy(busboyOptions)

  request.on('close', cleanup)
  request.on('error', cleanup)

  bb
    .on('field', onField)
    .on('file', onFile)
    .on('close', cleanup)
    .on('error', onEnd)
    .on('end', onEnd)
    .on('finish', onEnd)

  bb.on('partsLimit', function () {
    onError(new PartsLimitError())
  })

  bb.on('filesLimit', function () {
    onError(new FilesLimitError())
  })

  bb.on('fieldsLimit', function () {
    onError(new FieldsLimitError())
  })

  request.pipe(bb)

  function onField (name, fieldValue, fieldnameTruncated, valueTruncated, encoding, contentType) {
    // don't overwrite prototypes
    if (getDescriptor(Object.prototype, name)) {
      onError(new PrototypeViolationError())
      return
    }

    // If it is a JSON field, parse it
    if (contentType.startsWith('application/json')) {
      // If the value was truncated, it can never be a valid JSON. Don't even try to parse
      if (valueTruncated) {
        onError(new InvalidJSONFieldError())
        return
      }

      try {
        fieldValue = secureJSON.parse(fieldValue)
        contentType = 'application/json'
      } catch (e) {
        onError(new InvalidJSONFieldError())
        return
      }
    }

    const value = {
      fieldname: name,
      mimetype: contentType,
      encoding,
      value: fieldValue,
      fieldnameTruncated,
      valueTruncated,
      fields: body
    }

    if (body[name] === undefined) {
      body[name] = value
    } else if (Array.isArray(body[name])) {
      body[name].push(value)
    } else {
      body[name] = [body[name], value]
    }

    ch(value)
  }

  function onFile (name, file, filename, encoding, mimetype) {
    // don't overwrite prototypes
    if (getDescriptor(Object.prototype, name)) {
      // ensure that stream is consumed, any error is suppressed
      sendToWormhole(file)
      onError(new PrototypeViolationError())
      return
    }

    const throwFileSizeLimit = typeof options.throwFileSizeLimit === 'boolean'
      ? options.throwFileSizeLimit
      : defaultThrowFileSizeLimit

    const value = {
      fieldname: name,
      filename,
      encoding,
      mimetype,
      file,
      fields: body,
      _buf: null,
      async toBuffer () {
        if (this._buf) {
          return this._buf
        }
        const fileChunks = []
        let err
        for await (const chunk of this.file) {
          fileChunks.push(chunk)

          if (throwFileSizeLimit && this.file.truncated) {
            err = new RequestFileTooLargeError()
            err.part = this

            onError(err)
            fileChunks.length = 0
          }
        }
        if (err) {
          // throwing in the async iterator will
          // cause the file.destroy() to be called
          // The stream has already been managed by
          // busboy instead
          throw err
        }
        this._buf = Buffer.concat(fileChunks)
        return this._buf
      }
    }

    if (throwFileSizeLimit) {
      file.on('limit', function () {
        const err = new RequestFileTooLargeError()
        err.part = value
        onError(err)
      })
    }

    if (body[name] === undefined) {
      body[name] = value
    } else if (Array.isArray(body[name])) {
      body[name].push(value)
    } else {
      body[name] = [body[name], value]
    }
    currentFile = file
    ch(value)
  }

  function onError (err) {
    lastError = err
    currentFile = null
  }

  function onEnd (err) {
    cleanup()

    ch(err || lastError)
  }

  function cleanup (err) {
    request.unpipe(bb)
    // in node 10 it seems that error handler is not called but request.aborted is set
    if ((err || request.aborted) && currentFile) {
      currentFile.destroy()
    }
  }

  return parts
}

v8::Handle<v8::Value> V8WebGLRenderingContext::getShaderParameterCallback(const v8::Arguments& args)
{
     INC_STATS("DOM.WebGLRenderingContext.getShaderParameter()");

     if (args.Length() != 2)
        return V8Proxy::throwNotEnoughArgumentsError();

     ExceptionCode ec = 0;
     WebGLRenderingContext* context = V8WebGLRenderingContext::toNative(args.Holder());
    if (args.Length() > 0 && !isUndefinedOrNull(args[0]) && !V8WebGLShader::HasInstance(args[0])) {
        V8Proxy::throwTypeError();
        return notHandledByInterceptor();
    }
    WebGLShader* shader = V8WebGLShader::HasInstance(args[0]) ? V8WebGLShader::toNative(v8::Handle<v8::Object>::Cast(args[0])) : 0;
    unsigned pname = toInt32(args[1]);
    WebGLGetInfo info = context->getShaderParameter(shader, pname, ec);
    if (ec) {
        V8Proxy::setDOMException(ec, args.GetIsolate());
        return v8::Undefined();
    }
    return toV8Object(info, args.GetIsolate());
}

private void generateEntries(Block parentBlock, SyndFeed feed, RssMacroParameters parameters)
    throws MacroExecutionException
{
    int maxElements = parameters.getCount();
    int count = 0;

    for (Object item : feed.getEntries()) {
        ++count;
        if (count > maxElements) {
            break;
        }
        SyndEntry entry = (SyndEntry) item;

        ResourceReference titleResourceReference = new ResourceReference(entry.getLink(), ResourceType.URL);
        Block titleBlock = new LinkBlock(parsePlainText(entry.getTitle()), titleResourceReference, true);
        ParagraphBlock paragraphTitleBlock = new ParagraphBlock(Collections.singletonList(titleBlock));
        paragraphTitleBlock.setParameter(CLASS_ATTRIBUTE, "rssitemtitle");
        parentBlock.addChild(paragraphTitleBlock);

        if (parameters.isContent() && entry.getDescription() != null) {
            // We are wrapping the feed entry content in a HTML macro, not considering what the declared content
            // is, because some feed will declare text while they actually contain HTML.
            // See http://stuffthathappens.com/blog/2007/10/29/i-hate-rss/
            // A case where doing this might hurt is if a feed declares "text" and has any XML inside it does
            // not want to be interpreted as such, but displayed as is instead. But this certainly is too rare
            // compared to mis-formed feeds that say text while they want to say HTML.
            Block html = new RawBlock(entry.getDescription().getValue(), Syntax.XHTML_1_0);
            parentBlock.addChild(new GroupBlock(Arrays.asList(html), Collections.singletonMap(CLASS_ATTRIBUTE,
                "rssitemdescription")));
        }
    }
}

