static Jsi_RC jsi_BitfieldToValue(Jsi_Interp *interp, Jsi_OptionSpec* spec, Jsi_Value **outValue,
    Jsi_DString *outStr, void *record, Jsi_Wide flags)
{
    Jsi_csgset *bsget = spec->init.OPT_BITS;
    Jsi_Interp *d = interp;
    int idx = spec->idx;
    uchar *data = (uchar*)record;
    int64_t inum;
    Jsi_OptionSpec* enumSpec = (typeof(enumSpec))spec->data;

    if (!d || !bsget || idx<0) 
        return Jsi_LogBug("invalid bitfield");
    Jsi_RC rc = (*bsget)(interp, data, &inum, spec, idx, 0);
    if (rc != JSI_OK)
        return JSI_ERROR;

    if (enumSpec) {
        struct numStruct { int64_t numVal; } nval = { inum };
        Jsi_OptionSpec eSpec[] = {
            JSI_OPT(CUSTOM, struct numStruct, numVal, .help=spec->help, .flags=JSI_OPT_ENUM_SPEC, .custom=Jsi_Opt_SwitchEnum,
            .data=(void*)enumSpec, .info=0, .tname=spec->tname, .value=0, .bits=0, .boffset=8*sizeof(int64_t) ), //TODO: extra
            JSI_OPT_END(struct numStruct)
        };
        if (JSI_OK != jsi_EnumToValue(interp, eSpec, outValue, outStr, (void*)&nval, flags))
            return JSI_ERROR;
    } else if (outStr) {
        char obuf[100];
        snprintf(obuf, sizeof(obuf), "%" PRId64, inum);
        Jsi_DSAppend(outStr, obuf, NULL);
    } else {
        Jsi_Number num = (Jsi_Number)inum;
        Jsi_ValueMakeNumber(interp, outValue, num);
    }
    return JSI_OK;
}

protected function fixupImportedAttributes($modelName, X2Model &$model) {
    if ($modelName === 'Contacts' || $modelName === 'X2Leads')
        $this->fixupImportedContactName ($model);

    if ($modelName === 'Actions' && isset($model->associationType))
        $this->reconstructImportedActionAssoc($model);

    if ($model->hasAttribute('visibility')) {
        // Nobody every remembers to set visibility... set it for them
        if(empty($model->visibility) && ($model->visibility !== 0 && $model->visibility !== "0")
                || $model->visibility == 'Public') {
            $model->visibility = 1;
        } elseif($model->visibility == 'Private')
            $model->visibility = 0;
    }
    // If date fields were provided, do not create new values for them
    if (!empty($model->createDate) || !empty($model->lastUpdated) ||
            !empty($model->lastActivity)) {
        $now = time();
        if (empty($model->createDate))
            $model->createDate = $now;
        if (empty($model->lastUpdated))
            $model->lastUpdated = $now;
        if ($model->hasAttribute('lastActivity') && empty($model->lastActivity))
            $model->lastActivity = $now;
    }
    if($_SESSION['leadRouting'] == 1){
        $assignee = $this->getNextAssignee();
        if($assignee == "Anyone")
            $assignee = "";
        $model->assignedTo = $assignee;
    }
    // Loop through our override and set the manual data
    foreach($_SESSION['override'] as $attr => $val){
        $model->$attr = $val;
    }
}

