protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {

    HttpSession session = request.getSession(false);
    if (session == null) {
      AccessControlContext acc = AccessController.getContext();
      Subject subject = Subject.getSubject(acc);
      if (subject == null) {
        Helpers.doForbidden(response);
        return;
      }
      session = request.getSession(true);
      session.setAttribute("subject", subject);
    } else {
      Subject subject = (Subject) session.getAttribute("subject");
      if (subject == null) {
        session.invalidate();
        Helpers.doForbidden(response);
        return;
      }
    }

    String encoding = request.getHeader("Accept-Encoding");
    boolean supportsGzip = (encoding != null && encoding.toLowerCase().indexOf("gzip") > -1);
    SessionTerminal st = (SessionTerminal) session.getAttribute("terminal");
    if (st == null || st.isClosed()) {
        st = new SessionTerminal(getCommandProcessor(), getThreadIO());
        session.setAttribute("terminal", st);
    }
    String str = request.getParameter("k");
    String f = request.getParameter("f");
    String dump = st.handle(str, f != null && f.length() > 0);
    if (dump != null) {
        if (supportsGzip) {
            response.setHeader("Content-Encoding", "gzip");
            response.setHeader("Content-Type", "text/html");
            try {
                GZIPOutputStream gzos = new GZIPOutputStream(response.getOutputStream());
                gzos.write(dump.getBytes());
                gzos.close();
            } catch (IOException ie) {
                LOG.info("Exception writing response: ", ie);
            }
        } else {
            response.getOutputStream().write(dump.getBytes());
        }
    }
}

static ssize_t drop_sync(QIOChannel *ioc, size_t size)
{
    ssize_t ret = 0;
    char small[1024];
    char *buffer;

    buffer = sizeof(small) < size ? small : g_malloc(MIN(65536, size));
    while (size > 0) {
        ssize_t count = read_sync(ioc, buffer, MIN(65536, size));

        if (count <= 0) {
            goto cleanup;
        }
        assert(count <= size);
        size -= count;
        ret += count;
    }

 cleanup:
    if (buffer != small) {
        g_free(buffer);
    }
    return ret;
}

module.exports = function(path, opts, cb) {
  if (!cb) {
    cb = opts;
    opts = {};
  }

  var cmd = module.exports.cmd(path, opts);
  opts.timeout = opts.timeout || 5000;

  exec(cmd, opts, function(e, stdout, stderr) {
    if (e) { return cb(e); }
    if (stderr) { return cb(new Error(stderr)); }

    return cb(null, module.exports.parse(path, stdout, opts));
  });
};

private Subscriber<Object> buildSubscriber(NettyHttpRequest<?> request,
                                           ChannelHandlerContext context,
                                           RouteMatch<?> finalRoute) {
    return new CompletionAwareSubscriber<Object>() {
        Boolean alwaysAddContent = request.getContentType()
                .map(type -> type.equals(MediaType.APPLICATION_FORM_URLENCODED_TYPE))
                .orElse(false);
        RouteMatch<?> routeMatch = finalRoute;
        AtomicBoolean executed = new AtomicBoolean(false);
        AtomicLong pressureRequested = new AtomicLong(0);
        ConcurrentHashMap<String, UnicastProcessor> subjects = new ConcurrentHashMap<>();
        ConcurrentHashMap<Integer, HttpDataReference> dataReferences = new ConcurrentHashMap<>();
        ConversionService conversionService = ConversionService.SHARED;
        Subscription s;
        LongConsumer onRequest = (num) -> pressureRequested.updateAndGet((p) -> {
            long newVal = p - num;
            if (newVal < 0) {
                s.request(num - p);
                return 0;
            } else {
                return newVal;
            }
        });

        Flowable processFlowable(Flowable flowable, Integer dataKey, boolean controlsFlow) {
            if (controlsFlow) {
                flowable = flowable.doOnRequest(onRequest);
            }
            return flowable
                    .doAfterTerminate(() -> {
                        if (controlsFlow) {
                            HttpDataReference dataReference = dataReferences.get(dataKey);
                            dataReference.destroy();
                        }
                    });
        }

        @Override
        protected void doOnSubscribe(Subscription subscription) {
            this.s = subscription;
            subscription.request(1);
        }

        @Override
        protected void doOnNext(Object message) {
            boolean executed = this.executed.get();
            if (message instanceof ByteBufHolder) {
                if (message instanceof HttpData) {
                    HttpData data = (HttpData) message;

                    if (LOG.isTraceEnabled()) {
                        LOG.trace("Received HTTP Data for request [{}]: {}", request, message);
                    }

                    String name = data.getName();
                    Optional<Argument<?>> requiredInput = routeMatch.getRequiredInput(name);

                    if (requiredInput.isPresent()) {
                        Argument<?> argument = requiredInput.get();
                        Supplier<Object> value;
                        boolean isPublisher = Publishers.isConvertibleToPublisher(argument.getType());
                        boolean chunkedProcessing = false;

                        if (isPublisher) {
                            Integer dataKey = System.identityHashCode(data);
                            HttpDataReference dataReference = dataReferences.computeIfAbsent(dataKey, (key) -> {
                                return new HttpDataReference(data);
                            });
                            Argument typeVariable;

                            if (StreamingFileUpload.class.isAssignableFrom(argument.getType())) {
                                typeVariable = Argument.of(PartData.class);
                            } else {
                                typeVariable = argument.getFirstTypeVariable().orElse(Argument.OBJECT_ARGUMENT);
                            }
                            Class typeVariableType = typeVariable.getType();

                            UnicastProcessor namedSubject = subjects.computeIfAbsent(name, (key) -> UnicastProcessor.create());

                            chunkedProcessing = PartData.class.equals(typeVariableType) ||
                                    Publishers.isConvertibleToPublisher(typeVariableType) ||
                                    ClassUtils.isJavaLangType(typeVariableType);

                            if (Publishers.isConvertibleToPublisher(typeVariableType)) {
                                boolean streamingFileUpload = StreamingFileUpload.class.isAssignableFrom(typeVariableType);
                                if (streamingFileUpload) {
                                    typeVariable = Argument.of(PartData.class);
                                } else {
                                    typeVariable = typeVariable.getFirstTypeVariable().orElse(Argument.OBJECT_ARGUMENT);
                                }
                                dataReference.subject.getAndUpdate(subject -> {
                                    if (subject == null) {
                                        UnicastProcessor childSubject = UnicastProcessor.create();
                                        Flowable flowable = processFlowable(childSubject, dataKey, true);
                                        if (streamingFileUpload && data instanceof FileUpload) {
                                            namedSubject.onNext(new NettyStreamingFileUpload(
                                                    (FileUpload) data,
                                                    serverConfiguration.getMultipart(),
                                                    ioExecutor,
                                                    flowable));
                                        } else {
                                            namedSubject.onNext(flowable);
                                        }

                                        return childSubject;
                                    }
                                    return subject;
                                });

                            }

                            UnicastProcessor subject = Optional.ofNullable(dataReference.subject.get()).orElse(namedSubject);

                            Object part = data;

                            if (chunkedProcessing) {
                                HttpDataReference.Component component = dataReference.addComponent((e) -> {
                                    subject.onError(e);
                                    s.cancel();
                                });
                                if (component == null) {
                                    return;
                                }
                                part = new NettyPartData(dataReference, component);
                            }

                            if (data instanceof FileUpload &&
                                    StreamingFileUpload.class.isAssignableFrom(argument.getType())) {
                                dataReference.upload.getAndUpdate(upload -> {
                                    if (upload == null) {
                                        return new NettyStreamingFileUpload(
                                                (FileUpload) data,
                                                serverConfiguration.getMultipart(),
                                                ioExecutor,
                                                processFlowable(subject, dataKey, true));
                                    }
                                    return upload;
                                });
                            }

                            Optional<?> converted = conversionService.convert(part, typeVariable);

                            converted.ifPresent(subject::onNext);

                            if (data.isCompleted() && chunkedProcessing) {
                                subject.onComplete();
                            }

                            value = () -> {
                                StreamingFileUpload upload = dataReference.upload.get();
                                if (upload != null) {
                                    return upload;
                                } else {
                                    return processFlowable(namedSubject, dataKey, dataReference.subject.get() == null);
                                }
                            };

                        } else {
                            if (data instanceof Attribute && !data.isCompleted()) {
                                request.addContent(data);
                                s.request(1);
                                return;
                            } else {
                                value = () -> {
                                    if (data.refCnt() > 0) {
                                        return data;
                                    } else {
                                        return null;
                                    }
                                };
                            }
                        }

                        if (!executed) {
                            String argumentName = argument.getName();
                            if (!routeMatch.isSatisfied(argumentName)) {
                                routeMatch = routeMatch.fulfill(Collections.singletonMap(argumentName, value.get()));
                            }
                            if (isPublisher && chunkedProcessing) {
                                //accounting for the previous request
                                pressureRequested.incrementAndGet();
                            }
                            if (routeMatch.isExecutable() || message instanceof LastHttpContent) {
                                executeRoute();
                                executed = true;
                            }
                        }

                        if (alwaysAddContent) {
                            request.addContent(data);
                        }

                        if (!executed || !chunkedProcessing) {
                            s.request(1);
                        }

                    } else {
                        request.addContent(data);
                        s.request(1);
                    }
                } else {
                    request.addContent((ByteBufHolder) message);
                    s.request(1);
                }
            } else {
                ((NettyHttpRequest) request).setBody(message);
                s.request(1);
            }
        }

        @Override
        protected void doOnError(Throwable t) {
            try {
                s.cancel();
                exceptionCaught(context, t);
            } catch (Exception e) {
                // should never happen
                writeDefaultErrorResponse(context, request, e);
            }
        }

        @Override
        protected void doOnComplete() {
            for (UnicastProcessor subject: subjects.values()) {
                if (!subject.hasComplete()) {
                    subject.onComplete();
                }
            }
            executeRoute();
        }

        private void executeRoute() {
            if (executed.compareAndSet(false, true)) {
                try {
                    routeMatch = prepareRouteForExecution(routeMatch, request);
                    routeMatch.execute();
                } catch (Exception e) {
                    context.pipeline().fireExceptionCaught(e);
                }
            }
        }
    };
}

int Reverb_command(effect_handle_t  self,
 uint32_t            cmdCode,
 uint32_t            cmdSize,
 void *pCmdData,
 uint32_t *replySize,
 void *pReplyData){
    android::ReverbContext * pContext = (android::ReverbContext *) self;
    LVREV_ControlParams_st    ActiveParams; /* Current control Parameters */
    LVREV_ReturnStatus_en     LvmStatus=LVREV_SUCCESS; /* Function call status */


 if (pContext == NULL){
        ALOGV("\tLVM_ERROR : Reverb_command ERROR pContext == NULL");
 return -EINVAL;
 }


 switch (cmdCode){
 case EFFECT_CMD_INIT:

 if (pReplyData == NULL || replySize == NULL || *replySize != sizeof(int)){
                ALOGV("\tLVM_ERROR : Reverb_command cmdCode Case: "
 "EFFECT_CMD_INIT: ERROR");
 return -EINVAL;
 }
 *(int *) pReplyData = 0;
 break;

 case EFFECT_CMD_SET_CONFIG:
 if (pCmdData == NULL || cmdSize != sizeof(effect_config_t) ||
                    pReplyData == NULL || replySize == NULL || *replySize != sizeof(int)) {
                ALOGV("\tLVM_ERROR : Reverb_command cmdCode Case: "
 "EFFECT_CMD_SET_CONFIG: ERROR");
 return -EINVAL;
 }
 *(int *) pReplyData = android::Reverb_setConfig(pContext,
 (effect_config_t *) pCmdData);
 break;

 case EFFECT_CMD_GET_CONFIG:
 if (pReplyData == NULL || replySize == NULL || *replySize != sizeof(effect_config_t)) {
                ALOGV("\tLVM_ERROR : Reverb_command cmdCode Case: "
 "EFFECT_CMD_GET_CONFIG: ERROR");
 return -EINVAL;
 }

            android::Reverb_getConfig(pContext, (effect_config_t *)pReplyData);
 break;

 case EFFECT_CMD_RESET:
 Reverb_setConfig(pContext, &pContext->config);
 break;

 case EFFECT_CMD_GET_PARAM:{
 effect_param_t *p = (effect_param_t *)pCmdData;
 if (SIZE_MAX - sizeof(effect_param_t) < (size_t)p->psize) {
                android_errorWriteLog(0x534e4554, "26347509");
 return -EINVAL;
 }
 if (pCmdData == NULL || cmdSize < sizeof(effect_param_t) ||
                    cmdSize < (sizeof(effect_param_t) + p->psize) ||
                    pReplyData == NULL || replySize == NULL ||
 *replySize < (sizeof(effect_param_t) + p->psize)) {
                ALOGV("\tLVM_ERROR : Reverb_command cmdCode Case: "
 "EFFECT_CMD_GET_PARAM: ERROR");
 return -EINVAL;
 }

            memcpy(pReplyData, pCmdData, sizeof(effect_param_t) + p->psize);

            p = (effect_param_t *)pReplyData;

 int voffset = ((p->psize - 1) / sizeof(int32_t) + 1) * sizeof(int32_t);

            p->status = android::Reverb_getParameter(pContext,
 (void *)p->data,
 &p->vsize,
                                                          p->data + voffset);

 *replySize = sizeof(effect_param_t) + voffset + p->vsize;


 } break;
 case EFFECT_CMD_SET_PARAM:{


 if (pCmdData == NULL || (cmdSize < (sizeof(effect_param_t) + sizeof(int32_t))) ||
                    pReplyData == NULL ||  replySize == NULL || *replySize != sizeof(int32_t)) {
                ALOGV("\tLVM_ERROR : Reverb_command cmdCode Case: "
 "EFFECT_CMD_SET_PARAM: ERROR");
 return -EINVAL;
 }

 effect_param_t *p = (effect_param_t *) pCmdData;

 if (p->psize != sizeof(int32_t)){
                ALOGV("\t4LVM_ERROR : Reverb_command cmdCode Case: "
 "EFFECT_CMD_SET_PARAM: ERROR, psize is not sizeof(int32_t)");
 return -EINVAL;
 }



             *(int *)pReplyData = android::Reverb_setParameter(pContext,
                                                              (void *)p->data,
                                                              p->data + p->psize);
         } break;

         case EFFECT_CMD_ENABLE:

 if (pReplyData == NULL || *replySize != sizeof(int)){
                ALOGV("\tLVM_ERROR : Reverb_command cmdCode Case: "
 "EFFECT_CMD_ENABLE: ERROR");
 return -EINVAL;
 }
 if(pContext->bEnabled == LVM_TRUE){
                 ALOGV("\tLVM_ERROR : Reverb_command cmdCode Case: "
 "EFFECT_CMD_ENABLE: ERROR-Effect is already enabled");
 return -EINVAL;
 }
 *(int *)pReplyData = 0;
            pContext->bEnabled = LVM_TRUE;
 /* Get the current settings */
 LvmStatus = LVREV_GetControlParameters(pContext->hInstance, &ActiveParams);
            LVM_ERROR_CHECK(LvmStatus, "LVREV_GetControlParameters", "EFFECT_CMD_ENABLE")
            pContext->SamplesToExitCount =
 (ActiveParams.T60 * pContext->config.inputCfg.samplingRate)/1000;
            pContext->volumeMode = android::REVERB_VOLUME_FLAT;
 break;
 case EFFECT_CMD_DISABLE:

 if (pReplyData == NULL || *replySize != sizeof(int)){
                ALOGV("\tLVM_ERROR : Reverb_command cmdCode Case: "
 "EFFECT_CMD_DISABLE: ERROR");
 return -EINVAL;
 }
 if(pContext->bEnabled == LVM_FALSE){
                 ALOGV("\tLVM_ERROR : Reverb_command cmdCode Case: "
 "EFFECT_CMD_DISABLE: ERROR-Effect is not yet enabled");
 return -EINVAL;
 }
 *(int *)pReplyData = 0;
            pContext->bEnabled = LVM_FALSE;
 break;

 case EFFECT_CMD_SET_VOLUME:
 if (pCmdData == NULL ||
                cmdSize != 2 * sizeof(uint32_t)) {
                ALOGV("\tLVM_ERROR : Reverb_command cmdCode Case: "
 "EFFECT_CMD_SET_VOLUME: ERROR");
 return -EINVAL;
 }


 if (pReplyData != NULL) { // we have volume control
                pContext->leftVolume = (LVM_INT16)((*(uint32_t *)pCmdData + (1 << 11)) >> 12);
                pContext->rightVolume = (LVM_INT16)((*((uint32_t *)pCmdData + 1) + (1 << 11)) >> 12);
 *(uint32_t *)pReplyData = (1 << 24);
 *((uint32_t *)pReplyData + 1) = (1 << 24);
 if (pContext->volumeMode == android::REVERB_VOLUME_OFF) {
                    pContext->volumeMode = android::REVERB_VOLUME_FLAT;
 }
 } else { // we don't have volume control
                pContext->leftVolume = REVERB_UNIT_VOLUME;
                pContext->rightVolume = REVERB_UNIT_VOLUME;
                pContext->volumeMode = android::REVERB_VOLUME_OFF;
 }
            ALOGV("EFFECT_CMD_SET_VOLUME left %d, right %d mode %d",
                    pContext->leftVolume, pContext->rightVolume,  pContext->volumeMode);
 break;

 case EFFECT_CMD_SET_DEVICE:
 case EFFECT_CMD_SET_AUDIO_MODE:
 break;

 default:
            ALOGV("\tLVM_ERROR : Reverb_command cmdCode Case: "
 "DEFAULT start %d ERROR",cmdCode);
 return -EINVAL;
 }

 return 0;
} /* end Reverb_command */

