	var simpleValue = isSimple(value);
	var simpleCurr = isSimple(curr);

	// From kennedy to simple or sketch or vice versa
	var transition = (simpleCurr && value == 'default') ||
		(curr == 'default' && simpleValue);
	var noRestart = transition && (value != 'sketch' && curr != 'sketch');

	if (transition && !this.themeSwitching)
	{
		Editor.currentTheme = value;
		this.themeSwitching = true;
		var scrollState = this.saveScrollState();

		mxUtils.setPrefixedStyle(this.container.style, 'transition', 'all ' + delay + 'ms');

		if (delay == 0)
		{
			this.container.style.opacity = '0';
		}

		window.setTimeout(mxUtils.bind(this, function()
		{
			this.container.style.opacity = '0';

			window.setTimeout(mxUtils.bind(this, function()
			{
				if (simpleCurr && value == 'default')
				{
					if (this.sidebarFooterContainer != null)
					{
						this.sidebarFooterContainer.style.display = 'block';
					}

					this.menubarContainer.style.display = 'block';
					this.toolbarContainer.style.display = 'block';
					this.tabContainer.style.display = 'block';
					this.hsplit.style.display = 'block';
					this.hsplitPosition = EditorUi.prototype.hsplitPosition;
					this.menubarHeight = App.prototype.menubarHeight;
					this.formatWidth = EditorUi.prototype.formatWidth;
				}
				else if (curr == 'default' && simpleValue)
				{
					if (this.sidebarFooterContainer != null)
					{
						this.sidebarFooterContainer.style.display = 'none';
					}

					this.menubarContainer.style.display = 'none';
					this.toolbarContainer.style.display = 'none';
					this.tabContainer.style.display = 'none';
					this.hsplit.style.display = 'none';
					this.hsplitPosition = 0;
					this.menubarHeight = 0;
					this.formatWidth = 0;
				}

				this.switchTheme(value);

				window.setTimeout(mxUtils.bind(this, function()
				{
					this.fireEvent(new mxEventObject('currentThemeChanged'));
					this.editor.fireEvent(new mxEventObject('statusChanged'));
					this.editor.graph.refresh();
					this.restoreScrollState(scrollState);
					this.container.style.opacity = '';

					window.setTimeout(mxUtils.bind(this, function()
					{
						mxUtils.setPrefixedStyle(this.container.style, 'transition', null);
						delete this.themeSwitching;

						if (post != null)
						{
							post();
						}
					}), delay);
				}), delay);
			}), delay);
		}), 0);
	}

	return noRestart;
};

apr_status_t h2_stream_add_header(h2_stream *stream,
                                   const char *name, size_t nlen,
                                   const char *value, size_t vlen)
 {
     ap_assert(stream);

    if (!stream->has_response) {
        if (name[0] == ':') {
            if ((vlen) > stream->session->s->limit_req_line) {
                /* pseudo header: approximation of request line size check */
                ap_log_cerror(APLOG_MARK, APLOG_TRACE1, 0, stream->session->c,
                              "h2_stream(%ld-%d): pseudo header %s too long", 
                              stream->session->id, stream->id, name);
                return h2_stream_set_error(stream, 
                                           HTTP_REQUEST_URI_TOO_LARGE);
            }
        }
        else if ((nlen + 2 + vlen) > stream->session->s->limit_req_fieldsize) {
            /* header too long */
             ap_log_cerror(APLOG_MARK, APLOG_TRACE1, 0, stream->session->c,
                          "h2_stream(%ld-%d): header %s too long", 
                           stream->session->id, stream->id, name);
            return h2_stream_set_error(stream, 
                                       HTTP_REQUEST_HEADER_FIELDS_TOO_LARGE);
         }
        if (name[0] != ':') {
            ++stream->request_headers_added;
            if (stream->request_headers_added 
                > stream->session->s->limit_req_fields) {
                /* too many header lines */
                ap_log_cerror(APLOG_MARK, APLOG_TRACE1, 0, stream->session->c,
                              "h2_stream(%ld-%d): too many header lines", 
                              stream->session->id, stream->id);
                return h2_stream_set_error(stream, 
                                           HTTP_REQUEST_HEADER_FIELDS_TOO_LARGE);
            }
         }
     }

     if (h2_stream_is_scheduled(stream)) {
         return add_trailer(stream, name, nlen, value, vlen);
     }
     else {
         if (!stream->rtmp) {
             stream->rtmp = h2_req_create(stream->id, stream->pool, 
                                         NULL, NULL, NULL, NULL, NULL, 0);
        }
        if (stream->state != H2_STREAM_ST_OPEN) {
            return APR_ECONNRESET;
        }
        return h2_request_add_header(stream->rtmp, stream->pool,
                                     name, nlen, value, vlen);
    }
}

xsltAttributeComp(xsltStylesheetPtr style, xmlNodePtr inst) {
#ifdef XSLT_REFACTORED
    xsltStyleItemAttributePtr comp;
#else
    xsltStylePreCompPtr comp;
#endif

    /*
    * <xsl:attribute
    *   name = { qname }
    *   namespace = { uri-reference }>
    *   <!-- Content: template -->
    * </xsl:attribute>
    */
    if ((style == NULL) || (inst == NULL) || (inst->type != XML_ELEMENT_NODE))
	return;

#ifdef XSLT_REFACTORED
    comp = (xsltStyleItemAttributePtr) xsltNewStylePreComp(style,
	XSLT_FUNC_ATTRIBUTE);
#else
    comp = xsltNewStylePreComp(style, XSLT_FUNC_ATTRIBUTE);
#endif

    if (comp == NULL)
	return;
    inst->psvi = comp;
    comp->inst = inst;

    /*
    * Attribute "name".
    */
    /*
    * TODO: Precompile the AVT. See bug #344894.
    */
    comp->name = xsltEvalStaticAttrValueTemplate(style, inst,
				 (const xmlChar *)"name",
				 NULL, &comp->has_name);
    if (! comp->has_name) {
	xsltTransformError(NULL, style, inst,
	    "XSLT-attribute: The attribute 'name' is missing.\n");
	style->errors++;
	return;
    }
    /*
    * Attribute "namespace".
    */
    /*
    * TODO: Precompile the AVT. See bug #344894.
    */
    comp->ns = xsltEvalStaticAttrValueTemplate(style, inst,
	(const xmlChar *)"namespace",
	NULL, &comp->has_ns);

    if (comp->name != NULL) {
	if (xmlValidateQName(comp->name, 0)) {
	    xsltTransformError(NULL, style, inst,
		"xsl:attribute: The value '%s' of the attribute 'name' is "
		"not a valid QName.\n", comp->name);
	    style->errors++;
        } else if (xmlStrEqual(comp->name, BAD_CAST "xmlns")) {
	    xsltTransformError(NULL, style, inst,
                "xsl:attribute: The attribute name 'xmlns' is not allowed.\n");
	    style->errors++;
	} else {
	    const xmlChar *prefix = NULL, *name;

	    name = xsltSplitQName(style->dict, comp->name, &prefix);
	    if (prefix != NULL) {
		if (comp->has_ns == 0) {
		    xmlNsPtr ns;

		    /*
		    * SPEC XSLT 1.0:
		    *  "If the namespace attribute is not present, then the
		    *  QName is expanded into an expanded-name using the
		    *  namespace declarations in effect for the xsl:element
		    *  element, including any default namespace declaration.
		    */
		    ns = xmlSearchNs(inst->doc, inst, prefix);
		    if (ns != NULL) {
			comp->ns = xmlDictLookup(style->dict, ns->href, -1);
			comp->has_ns = 1;
 #ifdef XSLT_REFACTORED
 			comp->nsPrefix = prefix;
 			comp->name = name;
 #endif
 		    } else {
 			xsltTransformError(NULL, style, inst,
			    "xsl:attribute: The prefixed QName '%s' "
			    "has no namespace binding in scope in the "
			    "stylesheet; this is an error, since the "
			    "namespace was not specified by the instruction "
			    "itself.\n", comp->name);
			style->errors++;
		    }
		}
	    }
	}
    }
}

