	if (!bin || !bin->dynstr) {
		return NULL;
	}
 	if (shdr->sh_link > bin->ehdr.e_shnum) {
 		return NULL;
 	}
	if (shdr->sh_size < 1) {
 		return NULL;
 	}
 	sdb = sdb_new0 ();
	if (!sdb) {
		return NULL;
	}
	link_shdr = &bin->shdr[shdr->sh_link];
